package cn.mop.persistence;
import cn.mop.domain.DomainException;
import cn.mop.domain.notification.DeliveryReceiptState.*;
import cn.mop.persistence.DeliveryReceiptJournal.*;
import cn.mop.persistence.DeliveryReceiptSnapshotCodec.Scope;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import java.nio.file.*;
import java.security.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class DeliveryReceiptJournalTest {
 static UUID id(int n){return UUID.fromString("7f000000-0000-4000-8000-"+String.format("%012d",n));}
 final Instant at=Instant.parse("2026-10-21T00:00:00.123456789Z");
 final Scope scope=new Scope(id(1),id(2),new Deduplication(id(3),id(4),Channel.WEBHOOK,id(5),"OPENED"));
 Command command(int version,Transition t){return new Command(version,id(100+version),id(20),7,"journal-"+(version+1),t);}
 Receipt receipt(int request,int receipt,ReceiptStatus status,int offset){return new Receipt(id(1),id(2),id(request),id(receipt),status,at.plusNanos(offset));}
 List<Command> commands(){return List.of(command(0,new Started(id(6),at.plusNanos(1))),command(1,new ReceiptRecorded(receipt(6,8,ReceiptStatus.ACCEPTED,2),at.plusNanos(3))),command(2,new ReceiptRecorded(receipt(6,9,ReceiptStatus.FAILED,4),at.plusNanos(5))),command(3,new DeadLettered(at.plusNanos(6))),command(4,new Started(id(7),at.plusNanos(7))),command(5,new ReceiptRecorded(receipt(6,10,ReceiptStatus.DELIVERED,2),at.plusNanos(8))));}
 DeliveryReceiptJournal vector(){var j=DeliveryReceiptJournal.queued(scope,at);for(var c:commands())j=j.append(c).journal();return j;}
 DeliveryReceiptJournal restore(DeliveryReceiptJournal j){return DeliveryReceiptJournal.restore(j.root().bytes(),j.root().sha256(),scope,j.entries(),j.state().version(),j.headSha256());}
 void invalid(Runnable r){var e=assertThrows(DomainException.class,r::run);assertEquals(503,e.status);assertEquals("DELIVERY_JOURNAL_INVALID",e.code);assertNull(e.getCause());assertFalse(e.getMessage().contains("SYNTHETIC_PRIVATE"));}
 static Entry bytes(byte[] b)throws Exception{return new Entry(b,HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b)));}
 @Test void emptyRootAndEveryStatusRoundTrip(){var j=DeliveryReceiptJournal.queued(scope,at);assertEquals(Status.QUEUED,restore(j).state().status());for(var c:commands()){j=j.append(c).journal();var r=restore(j);assertEquals(j.state().transitions(),r.state().transitions());assertEquals(j.state().status(),r.state().status());assertEquals(j.headSha256(),r.headSha256());}}
 @Test void originalReplayReturnsCurrentDeliveredStateNotOldUnknown(){var j=restore(vector());var replay=j.append(commands().get(0));assertTrue(replay.replay());assertSame(j,replay.journal());assertEquals(1,replay.appliedVersion());assertEquals(Status.DELIVERED,replay.journal().state().status());assertEquals(6,replay.journal().entries().size());}
 @Test void originalCommandIdentityCannotChangeActorPermissionTracePayloadOrVersion(){var j=vector();var c=commands().get(0);for(var changed:List.of(new Command(0,c.commandId(),id(21),7,c.traceId(),c.transition()),new Command(0,c.commandId(),id(20),8,c.traceId(),c.transition()),new Command(0,c.commandId(),id(20),7,"different",c.transition()),new Command(1,c.commandId(),id(20),7,c.traceId(),c.transition()),new Command(0,c.commandId(),id(20),7,c.traceId(),new Started(id(30),at))))assertEquals(409,assertThrows(DomainException.class,()->j.append(changed)).status);}
 @Test void newlyNamedDuplicateReceiptDoesNotCreatePhantomVersion(){var j=vector();var duplicate=new Command(6,id(200),id(20),7,"duplicate",new ReceiptRecorded(receipt(6,8,ReceiptStatus.ACCEPTED,2),at.plusSeconds(1)));assertEquals(409,assertThrows(DomainException.class,()->j.append(duplicate)).status);assertEquals(6,j.state().version());}
 @Test void missingReorderedDuplicatedAndTruncatedEntriesFailClosed(){var j=vector();var removed=new ArrayList<>(j.entries());removed.remove(2);var swapped=new ArrayList<>(j.entries());Collections.swap(swapped,1,2);var doubled=new ArrayList<>(j.entries());doubled.set(2,doubled.get(1));for(var list:List.of(removed,swapped,doubled,j.entries().subList(0,5)))invalid(()->DeliveryReceiptJournal.restore(j.root().bytes(),j.root().sha256(),scope,list,6,j.headSha256()));}
 @Test void replacingHeadOrClaimedVersionFails(){var j=vector();invalid(()->DeliveryReceiptJournal.restore(j.root().bytes(),j.root().sha256(),scope,j.entries(),6,"0".repeat(64)));invalid(()->DeliveryReceiptJournal.restore(j.root().bytes(),j.root().sha256(),scope,j.entries(),5,j.headSha256()));}
 @Test void rootFromOtherScopeOrNotQueuedFails(){var j=vector();var foreign=new Scope(id(9),scope.deliveryId(),scope.key());invalid(()->DeliveryReceiptJournal.restore(j.root().bytes(),j.root().sha256(),foreign,j.entries(),6,j.headSha256()));var s=new DeliveryReceiptSnapshotCodec().encode(j.state());invalid(()->DeliveryReceiptJournal.restore(s.bytes(),s.sha256(),scope,List.of(),0,s.sha256()));}
 @Test void validOtherScopeChainCannotBeSpliced(){var other=DeliveryReceiptJournal.queued(new Scope(id(9),id(2),scope.key()),at).append(commands().get(0)).journal();var root=DeliveryReceiptJournal.queued(scope,at);invalid(()->DeliveryReceiptJournal.restore(root.root().bytes(),root.root().sha256(),scope,other.entries(),1,other.headSha256()));}
 @Test void forgedLengthTagAndTrailingBytesFailEvenWithRecomputedHash()throws Exception{var j=DeliveryReceiptJournal.queued(scope,at).append(commands().get(0)).journal();var original=j.entries().get(0).bytes();var tail=Arrays.copyOf(original,original.length+1);var bad=original.clone();bad[bad.length-29]=(byte)99;for(var content:List.of(Arrays.copyOf(original,original.length-1),tail,bad)){var e=bytes(content);invalid(()->DeliveryReceiptJournal.restore(j.root().bytes(),j.root().sha256(),scope,List.of(e),1,e.sha256()));}}
 @Test void nonCanonicalModifiedUtfIsRejected()throws Exception{var j=DeliveryReceiptJournal.queued(scope,at).append(commands().get(0)).journal();var b=j.entries().get(0).bytes();var v=new byte[b.length+1];System.arraycopy(b,0,v,0,2);v[1]++;v[2]=(byte)0xc1;v[3]=(byte)0x8d;System.arraycopy(b,3,v,4,b.length-3);var e=bytes(v);invalid(()->DeliveryReceiptJournal.restore(j.root().bytes(),j.root().sha256(),scope,List.of(e),1,e.sha256()));}
 @Test void commandAndByteLimitsFailWithoutAllocatingUnboundedHistory(){var t=commands().get(0).transition();for(long v:new long[]{-1,12000,Long.MAX_VALUE})assertThrows(DomainException.class,()->new Command(v,id(100),id(20),7,"trace",t));for(String trace:List.of("","x\n","SYNTHETIC_PRIVATE secret","x".repeat(129)))assertThrows(DomainException.class,()->new Command(0,id(100),id(20),7,trace,t));assertThrows(DomainException.class,()->new Entry(new byte[1025],"0".repeat(64)));invalid(()->DeliveryReceiptJournal.restore(new byte[0],"",scope,Collections.nCopies(12001,null),12001,""));}
 @Test void defensiveByteAndListCopiesProtectOriginal(){var j=vector();var root=j.root().bytes();root[0]^=1;var bytes=j.entries().get(0).bytes();bytes[0]^=1;assertThrows(UnsupportedOperationException.class,()->j.entries().clear());assertEquals(Status.DELIVERED,restore(j).state().status());var supplied=new ArrayList<>(j.entries());var restored=DeliveryReceiptJournal.restore(j.root().bytes(),j.root().sha256(),scope,supplied,6,j.headSha256());supplied.clear();assertEquals(6,restored.entries().size());}
 @Test void unknownAndDeliveredCannotBecomeAutomaticallyRetryable(){var unknown=DeliveryReceiptJournal.queued(scope,at).append(commands().get(0)).journal();assertEquals(Status.UNKNOWN,restore(unknown).state().status());assertThrows(DomainException.class,()->unknown.append(command(1,new Started(id(30),at.plusSeconds(10)))));var delivered=restore(vector());assertThrows(DomainException.class,()->delivered.append(command(6,new Started(id(31),at.plusSeconds(10)))));assertFalse(delivered.databasePersisted());assertFalse(delivered.providerReceiptVerified());assertFalse(delivered.automaticSendEnabled());assertNull(delivered.state().effectiveRetryBudget());assertNull(delivered.state().effectiveSmsQuota());}
 @Test void rootAndEntriesMatchIndependentPythonVector()throws Exception{var file=Path.of("../../fixtures/delivery-receipt-journal-vector-20261021.json");var expected=new ObjectMapper().readTree(Files.readString(file));var j=vector();assertEquals(expected.get("root_hex").asText(),HexFormat.of().formatHex(j.root().bytes()));assertEquals(expected.get("root_sha256").asText(),j.root().sha256());assertEquals(expected.get("head_sha256").asText(),j.headSha256());assertEquals(expected.get("bytes").asInt(),j.encodedBytes());for(int i=0;i<6;i++){assertEquals(expected.get("entries").get(i).get("hex").asText(),HexFormat.of().formatHex(j.entries().get(i).bytes()));assertEquals(expected.get("entries").get(i).get("sha256").asText(),j.entries().get(i).sha256());}}
 @Test void incrementalStorageDoesNotRepeatWholeHistoricalSnapshots(){var j=DeliveryReceiptJournal.queued(scope,at).append(commands().get(0)).journal();int size=-1;for(int n=1;n<=200;n++){j=j.append(new Command(n,id(300+n),id(20),7,"bounded",new ReceiptRecorded(receipt(6,600+n,ReceiptStatus.ACCEPTED,n+1),at.plusNanos(n+1)))).journal();int bytes=j.entries().get(n).bytes().length;if(size<0)size=bytes;assertEquals(size,bytes);}assertEquals(201,j.entries().size());assertEquals(j.state().transitions(),restore(j).state().transitions());assertTrue(j.encodedBytes()<210*DeliveryReceiptJournal.MAX_ENTRY_BYTES);}
}
